import { ok, fail } from './result.js';
import { getCustomer, TIER_DISCOUNTS, normalizeId } from './customers.js';
import { getProduct } from './catalogue.js';
import { nextInvoiceNumber } from './numbering.js';
import { roundCents } from './money.js';
import { isValidDate, addDays, lastDayOfMonth } from './dates.js';

/**
 * Calculate the total for a single line (qty × unitPrice).
 * @param {{ qty: number, unitPrice: number }} line
 * @returns {number}
 */
export function lineTotal(line) {
  return line.qty * line.unitPrice;
}

/**
 * Calculate subtotal, discount, VAT, voucher, and total for an invoice.
 * VAT is computed per line on the amount after discount, rounded per line, then summed.
 * Voucher is applied after VAT.
 * @param {{ lines: Array<{ qty: number, unitPrice: number, discountPercent?: number, vatRate: number }>, voucher?: { code: string, amount: number } }} invoice
 * @returns {{ subtotal: number, discount: number, vat: number, voucher: number, total: number }}
 */
export function invoiceTotals(invoice) {
  let subtotal = 0;
  let discount = 0;
  let vat = 0;

  for (const line of invoice.lines) {
    const total = lineTotal(line);
    subtotal += total;

    const discountPercent = line.discountPercent ?? 0;
    const lineDiscount = roundCents(total * discountPercent / 100);
    const clampedLineDiscount = Math.max(0, lineDiscount);
    discount += clampedLineDiscount;

    const lineAmount = total - clampedLineDiscount;
    const lineVat = roundCents(lineAmount * line.vatRate / 100);
    const clampedLineVat = Math.max(0, lineVat);
    vat += clampedLineVat;
  }

  const voucher = (invoice.voucher?.amount) ?? 0;
  const total = Math.max(0, subtotal - discount + vat - voucher);

  return {
    subtotal,
    discount,
    vat,
    voucher,
    total,
  };
}

/**
 * Add or increase a line on a draft invoice.
 * @param {{ status: string, lines: Array }} invoice
 * @param {{ sku: string, qty: number, discountPercent?: number }} line
 * @returns {{ ok: true, value: any } | { ok: false, error: string }}
 */
export function addLine(invoice, { sku, qty, discountPercent = 0 }) {
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');
  if (!Number.isInteger(qty) || qty <= 0) return fail('QTY_INVALID');

  if (!Number.isFinite(discountPercent) || discountPercent < 0 || discountPercent > 100) {
    return fail('DISCOUNT_INVALID');
  }

  const product = getProduct(sku);
  if (!product.ok) return product;

  const existingLine = invoice.lines.find((line) => line.sku === sku);

  let newLines;
  if (existingLine) {
    newLines = invoice.lines.map((line) => {
      if (line.sku === sku) {
        return { ...line, qty: line.qty + qty };
      }
      return line;
    });
  } else {
    newLines = [
      ...invoice.lines,
      {
        sku: product.value.sku,
        name: product.value.name,
        qty,
        unitPrice: product.value.unitPrice,
        vatRate: product.value.vatRate,
        discountPercent,
      },
    ];
  }

  return ok({
    ...invoice,
    lines: newLines,
  });
}

/**
 * Remove a line from a draft invoice.
 * @param {{ status: string, lines: Array }} invoice
 * @param {string} sku
 * @returns {{ ok: true, value: any } | { ok: false, error: string }}
 */
export function removeLine(invoice, sku) {
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  const lineIndex = invoice.lines.findIndex((line) => line.sku === sku);
  if (lineIndex === -1) return fail('LINE_NOT_FOUND');

  if (invoice.lines.length === 1) return fail('NO_LINES');

  const newLines = invoice.lines.filter((_, i) => i !== lineIndex);

  return ok({
    ...invoice,
    lines: newLines,
  });
}

/**
 * Apply a voucher to a draft invoice.
 * @param {{ status: string, voucher?: any }} invoice
 * @param {{ code: string, amount: number }} voucher
 * @returns {{ ok: true, value: any } | { ok: false, error: string }}
 */
export function applyVoucher(invoice, { code, amount }) {
  if (invoice.status !== 'draft') {
    return fail('NOT_DRAFT');
  }

  if (invoice.voucher) {
    return fail('VOUCHER_EXISTS');
  }

  if (!Number.isInteger(amount) || amount <= 0) {
    return fail('AMOUNT_INVALID');
  }

  return ok({
    ...invoice,
    voucher: { code, amount },
  });
}

/**
 * Issue a draft invoice (set its number and mark it issued).
 * @param {{ status: string, issueDate: string }} invoice
 * @param {Array<string>} existingNumbers
 * @returns {{ ok: true, value: any } | { ok: false, error: string }}
 */
export function issueInvoice(invoice, existingNumbers) {
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  const number = nextInvoiceNumber(existingNumbers, invoice.issueDate);

  return ok({
    ...invoice,
    number,
    status: 'issued',
  });
}

/**
 * Create an invoice with the given customer and line items.
 * @param {{ customerId: string, issueDate: string, lines: Array<{ sku: string, qty: number }>, terms?: string }} invoice
 * @returns {{ ok: true, value: { customerId: string, issueDate: string, status: string, lines: Array, terms: string, dueDate: string } } | { ok: false, error: string }}
 */
export function createInvoice({ customerId, issueDate, lines, terms = 'NET30' }) {
  const normalizedCustomerId = normalizeId(customerId);
  const customer = getCustomer(normalizedCustomerId);
  if (!customer.ok) return customer;

  if (!isValidDate(issueDate)) return fail('DATE_INVALID');

  if (!['NET14', 'NET30', 'EOM'].includes(terms)) {
    return fail('TERMS_INVALID');
  }

  if (!Array.isArray(lines) || lines.length === 0) return fail('NO_LINES');

  const invoiceLines = [];
  for (const line of lines) {
    if (!Number.isInteger(line.qty) || line.qty <= 0) return fail('QTY_INVALID');

    const discountPercent =
      'discountPercent' in line ? line.discountPercent : TIER_DISCOUNTS[customer.value.tier];
    if (!Number.isFinite(discountPercent) || discountPercent < 0 || discountPercent > 100) {
      return fail('DISCOUNT_INVALID');
    }

    const product = getProduct(line.sku);
    if (!product.ok) return product;

    invoiceLines.push({
      sku: line.sku,
      name: product.value.name,
      qty: line.qty,
      unitPrice: product.value.unitPrice,
      vatRate: product.value.vatRate,
      discountPercent,
    });
  }

  let dueDate;
  if (terms === 'NET14') {
    dueDate = addDays(issueDate, 14);
  } else if (terms === 'NET30') {
    dueDate = addDays(issueDate, 30);
  } else if (terms === 'EOM') {
    dueDate = lastDayOfMonth(issueDate);
  }

  return ok({
    customerId: normalizedCustomerId,
    customerName: customer.value.name,
    issueDate,
    terms,
    dueDate,
    status: 'draft',
    lines: invoiceLines,
  });
}

